import assert from "node:assert/strict";
import fs from "node:fs";
import test from "node:test";

import * as yaml from "js-yaml";

import { charaLink, stockIdToLinkImpl } from "./chara.js";
import { contributorIncludes, splitFrontMatter } from "./contrib-guard.js";
import { buildEditorData, editorDataToRenderData } from "./editor-data.js";
import { lahItem, lahItemIcon } from "./item.js";
import { CharaIndex } from "./chara.js";
import { IntKeyMap } from "./int-key-map.js";

// The real data of the repository (generated by the masterdata step in CI), and the real chara pages
// parsed from their front matter.
const hasData = fs.existsSync("_data/ItemMaster.json") && fs.existsSync("_data/CardMaster.json");

function setup() {
const readJson = (name) => JSON.parse(fs.readFileSync(`_data/${name}.json`, "utf8"));
const data = {
  ItemMaster: readJson("ItemMaster"),
  CardMaster: readJson("CardMaster"),
  SidekickMaster: readJson("SidekickMaster"),
  wiki: { Item: new IntKeyMap(yaml.load(fs.readFileSync("_data/wiki/Item.yml", "utf8"), { json: true })) },
};
const charas = fs
  .readdirSync("_charas")
  .filter((f) => f.endsWith(".md"))
  .map((f) => {
    const slug = f.slice(0, -3);
    const doc = yaml.load(splitFrontMatter(fs.readFileSync(`_charas/${f}`, "utf8")).frontMatter.replace(/^---\r?\n|\r?\n---\r?\n?$/g, "")) ?? {};
    return { unreleased: false, ...doc, url: `/charas/${slug}/` };
  });

const editorData = buildEditorData({ data, charas, version: "test" });
const json = JSON.stringify(editorData);
const { charaDeps: previewDeps, itemData } = editorDataToRenderData(JSON.parse(json));

const realIndex = new CharaIndex();
realIndex.rebuild(charas);
const realDeps = { index: realIndex, data };
return { data, charas, editorData, json, previewDeps, itemData, realDeps };
}
const { data, charas, editorData, json, previewDeps, itemData, realDeps } = hasData ? setup() : {};

test("editor data: shape and size", { skip: !hasData && "needs _data (masterdata)" }, () => {
  assert.equal(editorData.version, "test");
  assert.equal(editorData.charas.length, charas.length);
  const ryekie = editorData.charas.find((c) => c.title === "Ryekie");
  assert.equal(ryekie.url, "/charas/ryekie/");
  assert.equal(ryekie.characterId, 4);
  assert.match(ryekie.cards.h1, /^\w+$/);
  assert.ok(Object.keys(editorData.items).every((k) => k === "3"));
  const first = Object.values(editorData.items[3])[0];
  assert.deepEqual(Object.keys(first).filter((k) => k !== "wiki").sort(), ["icon", "name"]);
  assert.ok(json.length < 150_000, `editor-data.json is ${json.length} bytes`);
  // unreleased pages carry the unreleased flag (and their icon)
  assert.ok(editorData.charas.some((c) => c.unreleased));
  assert.ok(editorData.charas.filter((c) => c.unreleased).every((c) => c.cards === undefined && c.characterId === undefined));
});

test("chara_link renders the same from the trimmed data as from the site data", { skip: !hasData && "needs _data (masterdata)" }, () => {
  let n = 0;
  for (const chara of charas) {
    for (const suffix of ["", "|h1", "|h2", "|h3", "|s1", "|s2", "|s3", "|h"]) {
      const input = `${chara.title}${suffix}`;
      assert.equal(charaLink(input, previewDeps), charaLink(input, realDeps), input);
      n++;
    }
  }
  assert.ok(n > 500);
  // an unknown name is printed as written
  assert.equal(charaLink("Nobody", previewDeps), "Nobody");
});

test("items render the same from the trimmed data (name and icon; tooltips are empty)", { skip: !hasData && "needs _data (masterdata)" }, () => {
  const strip = (html) => html.replace(/ data-content="[^"]*"/, "");
  let n = 0;
  for (const id of Object.keys(data.ItemMaster)) {
    assert.equal(strip(lahItem(Number(id), undefined, undefined, itemData, previewDeps)), strip(lahItem(Number(id), undefined, undefined, data, realDeps)), id);
    assert.equal(strip(lahItemIcon(Number(id), undefined, undefined, itemData)), strip(lahItemIcon(Number(id), undefined, undefined, data)), id);
    n++;
  }
  assert.ok(n > 500);
  // by wiki name, as in {% include item.html name="Ether Crystal" %}
  const named = Object.values(editorData.items[3]).find((i) => i.wiki);
  assert.equal(strip(lahItem(null, undefined, named.name, itemData, previewDeps)), strip(lahItem(null, undefined, named.name, data, realDeps)));
});

test("cards of chara pages render as chara links, like the build", { skip: !hasData && "needs _data (masterdata)" }, () => {
  let n = 0;
  for (const chara of charas.filter((c) => !c.unreleased)) {
    for (const [key, resourceName] of Object.entries(editorData.charas.find((c) => c.title === chara.title).cards ?? {})) {
      const stockId = (1000 + chara.characterId) * 10 + Number(key.slice(1));
      const cardId = stockId * 10 + 1;
      const type = key[0] === "h" ? 1 : 2;
      assert.equal(lahItem(cardId, type, undefined, itemData, previewDeps), lahItem(cardId, type, undefined, data, realDeps), key);
      assert.equal(stockIdToLinkImpl(stockId, type, previewDeps)[1], stockIdToLinkImpl(stockId, type, realDeps)[1]);
      assert.ok(resourceName);
      n++;
    }
  }
  assert.ok(n > 100);
});

test("contributor includes are computed from the real _includes folder", () => {
  const list = contributorIncludes(fs.readdirSync("_includes", { recursive: true }).map((f) => f.replaceAll("\\", "/")));
  assert.ok(list.includes("item.html"));
  assert.ok(!list.includes("header.html"));
});
